#ifndef ORIVA_UPDATE_H
#define ORIVA_UPDATE_H
#include "noctra-update-core.h"
#define UPDATE_CHECK 600
#define UPDATE_DOWNLOAD 601
#define UPDATE_FOUND (WM_APP+6)
#define UPDATE_READY (WM_APP+7)
static HWND updateButton;static BOOL updateAvailable=FALSE,updateQuiet=TRUE,updateChecked=FALSE,updateInstallRequested=FALSE,updateLaunchReady=FALSE;static wchar_t updateVersion[40],updatePath[256],updateHash[65],updateStage[32768];static ULONGLONG updateSize;
static BOOL updateDirectories(wchar_t*target,wchar_t*folder){DWORD n=GetModuleFileNameW(NULL,target,32768);if(!n||n>=32768)return FALSE;wchar_t base[32768];n=GetEnvironmentVariableW(L"LOCALAPPDATA",base,32768);if(!n||n>32000)return FALSE;swprintf(folder,32768,L"%ls\\Noctra",base);CreateDirectoryW(folder,NULL);wcscat(folder,L"\\Updates");CreateDirectoryW(folder,NULL);return TRUE;}
static BOOL updateFileHash(const wchar_t*path,const wchar_t*expected){if(!updateHex64(expected))return FALSE;HANDLE f=CreateFileW(path,GENERIC_READ,FILE_SHARE_READ,NULL,OPEN_EXISTING,FILE_FLAG_SEQUENTIAL_SCAN,NULL);if(f==INVALID_HANDLE_VALUE)return FALSE;HCRYPTPROV provider=0;HCRYPTHASH hash=0;BOOL ok=FALSE;BYTE digest[32],buffer[65536];DWORD n=0,size=32;if(!CryptAcquireContextW(&provider,NULL,NULL,PROV_RSA_AES,CRYPT_VERIFYCONTEXT)||!CryptCreateHash(provider,CALG_SHA_256,0,0,&hash))goto done;for(;;){if(!ReadFile(f,buffer,sizeof(buffer),&n,NULL))goto done;if(!n)break;if(!CryptHashData(hash,buffer,n,0))goto done;}if(!CryptGetHashParam(hash,HP_HASHVAL,digest,&size,0)||size!=32)goto done;wchar_t actual[65];for(int i=0;i<32;i++)swprintf(actual+i*2,3,L"%02x",digest[i]);actual[64]=0;ok=!_wcsicmp(actual,expected);done:if(hash)CryptDestroyHash(hash);if(provider)CryptReleaseContext(provider,0);CloseHandle(f);return ok;}
static void updateLayout(){if(!updateButton)return;SetWindowTextW(updateButton,busy?(action==UPDATE_CHECK?L"Checking...":L"Downloading..."):updateAvailable?L"Update available":L"Check updates");EnableWindow(updateButton,!busy&&!engine_setup_process);EnableWindow(GetDlgItem(window,ID_OPEN),!busy&&!engine_setup_process);}
static void updateNotify(){status(L"A new Noctra version is available. Click Update available to install it.");}
static void updateOffer(){wchar_t text[500];swprintf(text,500,L"Noctra %ls is available.\n\nInstall now? The launcher will close and reopen. Your engine and pairing settings are kept.",updateVersion);libraryDialogOpen=TRUE;if(MessageBoxW(window,text,L"Update Noctra",MB_YESNO|MB_ICONQUESTION|MB_DEFBUTTON2)==IDYES)updateInstallRequested=TRUE;libraryDialogOpen=FALSE;}
static void updateCommand(){if(busy||libraryDialogOpen)return;if(updateAvailable){updateOffer();if(updateInstallRequested){updateInstallRequested=FALSE;start(UPDATE_DOWNLOAD);}}else{updateQuiet=FALSE;start(UPDATE_CHECK);}}
static void updateCheckWorker(){DWORD code;char*r=requestMethod(L"GET",L"/downloads/windows-update.json",NULL,NULL,&code);int count=0;OJToken*t=NULL;wchar_t*version=NULL,*path=NULL,*hash=NULL;BOOL valid=FALSE;if(code==200&&r&&strlen(r)<65536&&(t=ojParse(r,&count))){version=ojWide(r,t,ojField(r,t,0,"version"));path=ojWide(r,t,ojField(r,t,0,"path"));hash=ojWide(r,t,ojField(r,t,0,"sha256"));int size=ojField(r,t,0,"size");char*bytes=size>=0?ojRaw(r,t,size):NULL;ULONGLONG offeredSize=bytes?strtoull(bytes,NULL,10):0;free(bytes);unsigned parts[4];valid=version&&wcslen(version)<40&&updateVersionParts(version,parts)&&updateSafePath(path)&&updateHex64(hash)&&offeredSize>0&&offeredSize<=20*1024*1024;if(valid&&updateIsNewer(version,APP_VERSION)){wcscpy(updateVersion,version);wcscpy(updatePath,path);wcscpy(updateHash,hash);updateSize=offeredSize;updateAvailable=TRUE;SendMessageW(window,UPDATE_FOUND,updateQuiet,0);}else if(valid&&!updateQuiet){wchar_t msg[160];swprintf(msg,160,tr(L"You have the latest Noctra version (%ls)."),APP_VERSION);status(msg);}}if(!valid&&!updateQuiet)status(tr(L"Could not check for updates. Check your connection and try again."));free(version);free(path);free(hash);free(t);free(r);}
static BOOL updateDownloadFile(){BOOL ok=FALSE;wchar_t target[32768],folder[32768],part[32768];HINTERNET ses=NULL,con=NULL,req=NULL;HANDLE out=INVALID_HANDLE_VALUE;if(!updateDirectories(target,folder)||wcslen(folder)>32000)return FALSE;swprintf(part,32768,L"%ls\\Noctra-update.part",folder);swprintf(updateStage,32768,L"%ls\\Noctra-update.exe",folder);DeleteFileW(part);out=CreateFileW(part,GENERIC_WRITE,0,NULL,CREATE_NEW,FILE_ATTRIBUTE_NORMAL|FILE_FLAG_SEQUENTIAL_SCAN,NULL);if(out==INVALID_HANDLE_VALUE)return FALSE;ses=WinHttpOpen(L"Noctra Updater/" APP_VERSION,WINHTTP_ACCESS_TYPE_AUTOMATIC_PROXY,WINHTTP_NO_PROXY_NAME,WINHTTP_NO_PROXY_BYPASS,0);if(!ses)goto done;WinHttpSetTimeouts(ses,15000,15000,180000,180000);con=WinHttpConnect(ses,L"noctra-link.soltairy.chatgpt.site",INTERNET_DEFAULT_HTTPS_PORT,0);if(!con)goto done;req=WinHttpOpenRequest(con,L"GET",updatePath,NULL,WINHTTP_NO_REFERER,WINHTTP_DEFAULT_ACCEPT_TYPES,WINHTTP_FLAG_SECURE);if(!req)goto done;DWORD redirects=WINHTTP_OPTION_REDIRECT_POLICY_NEVER;WinHttpSetOption(req,WINHTTP_OPTION_REDIRECT_POLICY,&redirects,sizeof(redirects));if(!WinHttpSendRequest(req,NULL,0,NULL,0,0,0)||!WinHttpReceiveResponse(req,NULL))goto done;DWORD code=0,n=sizeof(code);if(!WinHttpQueryHeaders(req,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,WINHTTP_HEADER_NAME_BY_INDEX,&code,&n,WINHTTP_NO_HEADER_INDEX)||code!=200)goto done;ULONGLONG total=0;BYTE buffer[65536];for(;;){DWORD got=0,wrote=0;if(!WinHttpReadData(req,buffer,sizeof(buffer),&got))goto done;if(!got)break;if(total+got>updateSize||!WriteFile(out,buffer,got,&wrote,NULL)||wrote!=got)goto done;total+=got;wchar_t msg[100];swprintf(msg,100,tr(L"Downloading update... %u%%"),(unsigned)(total*100/updateSize));status(msg);}if(total!=updateSize||!FlushFileBuffers(out))goto done;CloseHandle(out);out=INVALID_HANDLE_VALUE;if(!updateFileHash(part,updateHash)||!MoveFileExW(part,updateStage,MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))goto done;ok=TRUE;done:if(out!=INVALID_HANDLE_VALUE)CloseHandle(out);if(req)WinHttpCloseHandle(req);if(con)WinHttpCloseHandle(con);if(ses)WinHttpCloseHandle(ses);if(!ok)DeleteFileW(part);return ok;}
static void updateDownloadWorker(){if(updateDownloadFile())SendMessageW(window,UPDATE_READY,0,0);else status(tr(L"Could not download or verify the update. Your installed version is unchanged."));}
static BOOL updateBeginInstall(){wchar_t target[32768],folder[32768],current[32768],args[32768];if(!updateDirectories(target,folder))return FALSE;if(!updateFileHash(updateStage,updateHash)){status(tr(L"Update verification failed. Nothing was installed."));return FALSE;}if(swprintf(args,32768,L"--apply-update %lu \"%ls\" %ls",GetCurrentProcessId(),target,updateHash)<0)return FALSE;SHELLEXECUTEINFOW run={0};run.cbSize=sizeof(run);run.fMask=SEE_MASK_NOCLOSEPROCESS;run.hwnd=window;run.lpVerb=L"open";run.lpFile=updateStage;run.lpParameters=args;run.nShow=SW_SHOWNORMAL;libraryDialogOpen=TRUE;if(!ShellExecuteExW(&run)){libraryDialogOpen=FALSE;status(tr(L"Could not launch the updater. Noctra is still running."));return FALSE;}if(run.hProcess)CloseHandle(run.hProcess);DestroyWindow(window);return TRUE;}
static int updateApply(int argc,wchar_t**argv){if(argc!=5)return 1;wchar_t target[32768],folder[32768],module[32768],normalized[32768],next[32768],backup[32768];if(!updateDirectories(target,folder)||!updateHex64(argv[4]))return 1;DWORD pathLength=GetFullPathNameW(argv[3],32768,normalized,NULL);if(!pathLength||pathLength>=32768)return 1;const wchar_t*name=wcsrchr(normalized,L'\\');if(!name||_wcsicmp(name+1,L"Noctra.exe"))return 1;wcscpy(target,normalized);GetModuleFileNameW(NULL,module,32768);if(!updateFileHash(module,argv[4])){MessageBoxW(NULL,tr(L"Update verification failed. Your existing Noctra was not changed."),tr(L"Noctra update"),MB_OK|MB_ICONERROR);return 1;}wchar_t*end;unsigned long pid=wcstoul(argv[2],&end,10);if(!pid||*end||pid==GetCurrentProcessId())return 1;HANDLE parent=OpenProcess(SYNCHRONIZE|PROCESS_QUERY_LIMITED_INFORMATION,FALSE,(DWORD)pid);if(parent){wchar_t running[32768];DWORD capacity=32768;if(!QueryFullProcessImageNameW(parent,0,running,&capacity)||_wcsicmp(running,target)||WaitForSingleObject(parent,60000)!=WAIT_OBJECT_0){CloseHandle(parent);MessageBoxW(NULL,tr(L"Noctra did not close in time. The update was not installed."),tr(L"Noctra update"),MB_OK);return 1;}CloseHandle(parent);}else if(GetLastError()!=ERROR_INVALID_PARAMETER)return 1;swprintf(next,32768,L"%ls.next.exe",target);swprintf(backup,32768,L"%ls.previous.exe",target);BOOL installed=FALSE;if(CopyFileW(target,backup,FALSE)&&CopyFileW(module,next,FALSE)&&updateFileHash(next,argv[4])){for(int tries=0;tries<30;tries++){if(MoveFileExW(next,target,MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)){installed=TRUE;break;}Sleep(100);}}if(!installed){DeleteFileW(next);MessageBoxW(NULL,tr(L"Could not replace Noctra. Your existing installation was kept. Close other copies and try again."),tr(L"Noctra update"),MB_OK|MB_ICONINFORMATION);}ShellExecuteW(NULL,L"open",target,L"--library",NULL,SW_SHOWNORMAL);return installed?0:1;}
#endif
